 const frame=new THREE.Group();frame.name='NBIoT2 own SIM7028 module exact17.6×15.7×2.3 body,inferred installation';frame.position.fromArray(spec.module.position);frame.quaternion.copy(FACE.back);host.body.add(frame);const castellationCenters=[];for(const side of['left','right'])for(let i=0;i<9;i++)castellationCenters.push({n:castellationCenters.length+1,x:side==='left'?-8.8:8.8,y:(i-4)*1.1,side});for(const side of['top','bottom'])for(let i=0;i<12;i++)castellationCenters.push({n:castellationCenters.length+1,x:(i-5.5)*1.1,y:side==='top'?7.85:-7.85,side});
 const outline=new THREE.Shape(),rh=.2;outline.moveTo(-8.8,-7.85);for(const p of castellationCenters.filter(p=>p.side==='bottom').sort((a,b)=>a.x-b.x)){outline.lineTo(p.x-rh,p.y);outline.absarc(p.x,p.y,rh,Math.PI,0,true);}outline.lineTo(8.8,-7.85);for(const p of castellationCenters.filter(p=>p.side==='right').sort((a,b)=>a.y-b.y)){outline.lineTo(p.x,p.y-rh);outline.absarc(p.x,p.y,rh,-Math.PI/2,Math.PI/2,true);}outline.lineTo(8.8,7.85);for(const p of castellationCenters.filter(p=>p.side==='top').sort((a,b)=>b.x-a.x)){outline.lineTo(p.x+rh,p.y);outline.absarc(p.x,p.y,rh,0,Math.PI,true);}outline.lineTo(-8.8,7.85);for(const p of castellationCenters.filter(p=>p.side==='left').sort((a,b)=>b.y-a.y)){outline.lineTo(p.x,p.y+rh);outline.absarc(p.x,p.y,rh,Math.PI/2,-Math.PI/2,true);}outline.closePath();const module=solid(frame,outline,.6,[0,0,0],green,'NBIoT2 actual42LCC SIM7028 substrate with true edge half-holes'),lands=[],castellations=[],toes=[];for(const p of castellationCenters){const start={bottom:0,right:Math.PI/2,top:Math.PI,left:-Math.PI/2}[p.side],end=start+Math.PI;for(const[out,d,z,list,label]of[[.36,.05,.6,lands,'upper gold land'],[.27,.6,0,castellations,'plated half-hole barrel']]){const sh=new THREE.Shape();sh.absarc(0,0,out,start,end,false);sh.lineTo(rh*Math.cos(end),rh*Math.sin(end));sh.absarc(0,0,rh,end,start,true);sh.closePath();list.push(solid(frame,sh,d,[p.x,p.y,z],gold,'NBIoT2 SIM7028 actual '+label+' '+p.n));}const horizontal=p.side==='left'||p.side==='right',sign=p.side==='left'||p.side==='bottom'?-1:1;toes.push(mesh(frame,new THREE.BoxGeometry(horizontal?.7:.6,horizontal?.6:.7,.06),metal,[p.x+(horizontal?sign*.18:0),p.y+(horizontal?0:sign*.18),.01],'NBIoT2 actual module carrier solder toe '+p.n));}
