function simAssembly(host,service){const frame=new THREE.Group();frame.name='NBIoT2 actual internal NanoSIM socket envelope,exact retaining mechanism inferred';frame.position.fromArray(spec.sim.position);frame.quaternion.copy(FACE.back);host.body.add(frame);const black=materials.plastic(0x1c241c,{roughness:.87}),metal=materials.metal(0xb9bfaf,{roughness:.52}),gold=materials.metal(0xc3aa58,{roughness:.48}),base=slab(frame,14,12,.4,.3,[0,0,0],black,[],.01);base.name='NBIoT2 NanoSIM actual dielectric carrier';const rails=[];for(const sign of[-1,1])rails.push(mesh(frame,new THREE.BoxGeometry(.5,11.5,1.05),metal,[sign*6.75,0,.925],'NBIoT2 NanoSIM actual fixed side-guide envelope'));const rear=mesh(frame,new THREE.BoxGeometry(13,.4,1.05),metal,[0,5.65,.925],'NBIoT2 NanoSIM actual fixed rear stop'),contacts=[];for(const x of[-2.2,2.2])for(const y of[-2.5,0,2.5])contacts.push(mesh(frame,new THREE.BoxGeometry(1.1,1.8,.2),gold,[x,y,.55],'NBIoT2 NanoSIM actual fixed gold leaf-contact envelope'));const cover=slab(frame,14,11.5,.2,.3,[0,0,1.25],metal,[],.01);cover.name='NBIoT2 NanoSIM actual fixed protective lid,no claimed hinge or card included';const tails=[];for(const sign of[-1,1])for(let i=0;i<3;i++)tails.push(mesh(frame,new THREE.BoxGeometry(.8,.6,.12),metal,[sign*7.1,(i-1)*2.5,.06],'NBIoT2 NanoSIM actual fixed solder toe envelope'));const anchor=service?host.add(new Component({id:'sim',label:'Internal NanoSIM socket · rear cover removed',position:spec.sim.position,meta:{role:'visual-anchor',serviceOnly:true,source:'Own U111-B product confirms built-in NanoSIM;actual rear half and three hex fixings are removable assembly parts.Exact holder envelope/retaining mechanism/installation reconstructed.',scope:'Passive internal socket position only;no closed-shell clickthrough,SIMcard accessory,insertion animation,SIMdata,cellular,authentication,electrical or firmware behavior'}})):null;return{frame,base,rails,rear,contacts,cover,tails,anchor};}
