function screws(host){const out=[],metal=materials.metal(0xafb8aa,{roughness:.45});for(const[x,y]of spec.rearCover.screwPositions){const s=new THREE.Shape();s.absarc(0,0,1.5,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=i*tau/6;if(i)h.lineTo(.6*Math.cos(a),.6*Math.sin(a));else h.moveTo(.6*Math.cos(a),.6*Math.sin(a));}h.closePath();s.holes.push(h);const head=solid(host.body,s,.42,[x,y,-3.95],metal,'NBIoT2 actual fixed rear screw annular hex head'),blind=mesh(host.body,new THREE.CylinderGeometry(.6,.6,.12,6).rotateX(Math.PI/2),materials.metal(0x5f675b),[x,y,-3.47],'NBIoT2 actual fixed rear screw blind hex floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.58,.58,4.8,24).rotateX(Math.PI/2),metal,[x,y,-.8],'NBIoT2 actual fixed rear screw shank');out.push({head,blind,shank});}return out;}
export function buildNBIoT2(host,{rearCover=true,antenna=false,antennaAngleDeg=0}={}){if(typeof rearCover!=='boolean'||typeof antenna!=='boolean')throw new TypeError('rearCover/antenna must be booleans');const selected=data.filter(p=>rearCover||p.assemblySubset==='front'),parts=addCadParts(host,selected,{shell:materials.plastic(0x454a43,{roughness:.9})}),pcb=board(host),sim=simAssembly(host,!rearCover),radio=feedline(host),input=grove(host),output=sma(host),fixing=rearCover?screws(host):[],labels={};for(const face of rearCover?['front','back']:['front']){const v=spec.labels[face],p=slab(host.body,...v.size,.08,.15,v.position,materials.plastic(0xd9ddd5,{roughness:.9}),[],.005);p.name='NBIoT2 actual '+face+' body adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}host.nbiot2Assembly={rearCover,parts,pcb,sim,radio,input,output,fixing,labels};host.unitStickers=addStickers(host);if(antenna)output.port.attach(new Antenna({angleDeg:antennaAngleDeg}));}
